# Nginx vhost for set10-r3.test
# Generated by CelikPanel — do not edit by hand / elle düzenlemeyin
# Site ID: 3 · Project type: php
server {
    listen 80;
    listen [::]:80;
    server_name set10-r3.test www.set10-r3.test;

    access_log /var/log/nginx/set10-r3.test-access.log;
    error_log /var/log/nginx/set10-r3.test-error.log;

    # Root-owned validation content only; never tenant public_html.
    location ^~ /.well-known/acme-challenge/ {
        root /var/lib/celikpanel-agent/acme-http-01/subscriptions/2/domains/3;
        try_files $uri =404;
    }

    root /var/www/celikpanel/subscriptions/2/sites/3/public_html;
    index index.php index.html index.htm;

    location / {

        try_files $uri $uri/ /index.php?$query_string;
    }

    location ~ \.php$ {
        include snippets/fastcgi-php.conf;
        fastcgi_pass unix:/var/run/php/php8.3-fpm-site3.sock;
        fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;
        include fastcgi_params;
    }
    location ~ /\.(?!well-known).* {
        deny all;
    }

    # set10: added by the server owner by hand
    location /owner-extra/ {
        return 200 "owner";
    }
}

